package glitch

import data.glitch_lib

# Set definitions for CWE-326 detection
insecure_algorithms := {"DES", "3DES", "RC4", "AES-128", "SHA-1", "MD5", "SSLv2", "SSLv3", "TLSv1.0", "TLSv1.1"}
key_size_attributes := {"key_size", "key_length", "bits"}
mode_set := {"mode", "block_mode"}
protocol_attributes := {"tls_version", "ssl_version", "protocol"}
deprecated_protocols := {"TLSv1.0", "TLSv1.1", "SSLv2", "SSLv3"}
password_attributes := {"pbkdf2_iterations", "bcrypt_cost"}
encryption_attributes := {"encryption_enabled", "encryption_algorithm", "encryption_key"}
randomness_attributes := {"random_source", "seed", "nonce"}

# Check for insecure encryption algorithms
check_insecure_algorithm(value) {
    value.ir_type == "String"
    algorithm := lower(value.value)
    insecure_algorithm := insecure_algorithms[_]
    lower(insecure_algorithm) == algorithm
}

# Check for insufficient key lengths
check_insufficient_key_length(attr_name, value) {
    value.ir_type == "Integer"
    attr_name in key_size_attributes
    value.value < 2048  # Default threshold, can be adjusted per algorithm
}

# Check for insecure cipher modes
check_insecure_cipher_mode(value) {
    value.ir_type == "String"
    lower(value.value) == "ecb"
}

# Check for deprecated protocols
check_deprecated_protocol(value) {
    value.ir_type == "String"
    protocol := lower(value.value)
    deprecated_protocol := deprecated_protocols[_]
    lower(deprecated_protocol) == protocol
}

# Check for weak password-based encryption
check_weak_password_encryption(attr_name, value) {
    attr_name == "pbkdf2_iterations"
    value.ir_type == "Integer"
    value.value < 100000
} else {
    attr_name == "bcrypt_cost"
    value.ir_type == "Integer"
    value.value < 12
}

# Check for misconfigured encryption
check_misconfigured_encryption(attr_name, value) {
    attr_name == "encryption_enabled"
    value.ir_type == "Boolean"
    value.value == false
} else {
    attr_name == "encryption_key"
    value.ir_type == "String"
    (lower(value.value) == "default") or (lower(value.value) == "null")
}

